type Props = ModuleProps & { view?: 'contacts' | 'sales' | 'finance' | 'stock'; target?:NavigationTarget; navigate?:(target:NavigationTarget)=>void; contactKind?:'cliente'|'fornecedor' };
type FormModal = {type:'contact';contact?:Contact} | {type:'sale';sale?:Sale;initialStatus?:'vendida'|'reservada'|'orçamento'} | {type:'payment';bill:Bill;returnDirection?:Bill['direction']} | {type:'transition';sale:Sale;status:Sale['status']} | {type:'account'} | {type:'bill';direction?:Bill['direction']} | {type:'transfer'} | {type:'closing';accountId?:string} | {type:'product';product?:Product} | {type:'stock';product:Product} | {type:'reverse';paymentId:string};
type PurchaseModal = {type:'purchase';purchaseId?:string;productId?:string} | {type:'purchase-cancel';purchaseId:string};
type Modal = FormModal | PurchaseModal | {type:'contact-history';contact:Contact} | {type:'sale-detail';saleId:string} | {type:'bird-sales';birdId:string} | {type:'bills';direction:Bill['direction']|'ambas';initialStatus?:string;allDates?:boolean;clearSearch?:boolean;saleOnly?:boolean} | {type:'receipts';allDates?:boolean} | {type:'operations';criterion:'realizadas'|'reservada'} | {type:'bill-detail';billId:string} | {type:'closing-detail';closingId:string} | {type:'purchase-detail';purchaseId:string};
type CommercialContext = {type:'sale-detail'|'delivery-review'|'contact-history'|'bird-sales'|'bill-detail'|'closing-detail'|'purchase-detail';id:string}|{type:'bills';direction:Bill['direction']|'ambas';initialStatus:string;allDates:boolean;clearSearch:boolean;saleOnly:boolean}|{type:'receipts';allDates:boolean}|{type:'operations';criterion:'realizadas'|'reservada'}|null;
type CommercialRoute = {modal:CommercialContext;from:string;to:string;saleFilter:string;contactKind:string;stockFilter:string;stockDisplay:'materials'|'purchases';purchaseStatus:string};
function modalContext(modal:Modal|null):CommercialContext {
 if(!modal)return null;
 if(modal.type==='sale-detail')return {type:modal.type,id:modal.saleId};
 if(modal.type==='transition'&&modal.status==='entregue')return {type:'delivery-review',id:modal.sale.id};
 if(modal.type==='contact-history')return {type:modal.type,id:modal.contact.id};
 if(modal.type==='bird-sales')return {type:modal.type,id:modal.birdId};
 if(modal.type==='bill-detail')return {type:modal.type,id:modal.billId};
 if(modal.type==='closing-detail')return {type:modal.type,id:modal.closingId};
 if(modal.type==='purchase-detail')return {type:modal.type,id:modal.purchaseId};
 if(modal.type==='bills')return {type:modal.type,direction:modal.direction,initialStatus:modal.initialStatus??'abertas',allDates:!!modal.allDates,clearSearch:!!modal.clearSearch,saleOnly:!!modal.saleOnly};
 if(modal.type==='receipts')return {type:modal.type,allDates:!!modal.allDates};
 if(modal.type==='operations')return {type:modal.type,criterion:modal.criterion};
 return null;
}
function restoreModal(context:CommercialContext,state:State,scope:Props['scope']):Modal|null {
 if(!context)return null;
 if(context.type==='bills'||context.type==='receipts'||context.type==='operations')return context;
 if(context.type==='sale-detail'&&state.sales.some(s=>s.id===context.id&&s.scope===scope))return {type:'sale-detail',saleId:context.id};
 if(context.type==='delivery-review'){const sale=state.sales.find(s=>s.id===context.id&&s.scope===scope);return sale?.status==='vendida'?{type:'transition',sale,status:'entregue'}:sale?{type:'sale-detail',saleId:sale.id}:null;}
 if(context.type==='contact-history'){const contact=state.contacts.find(c=>c.id===context.id&&c.scope===scope);return contact?{type:'contact-history',contact}:null;}
 if(context.type==='bird-sales'&&state.birds.some(b=>b.id===context.id&&b.scope===scope))return {type:'bird-sales',birdId:context.id};
 if(context.type==='bill-detail'&&state.bills.some(b=>b.id===context.id&&b.scope===scope))return {type:'bill-detail',billId:context.id};
 if(context.type==='closing-detail'&&state.closings.some(c=>c.id===context.id&&c.scope===scope))return {type:'closing-detail',closingId:context.id};
 if(context.type==='purchase-detail'&&state.purchases.some(p=>p.id===context.id&&p.scope===scope))return {type:'purchase-detail',purchaseId:context.id};
 return null;
}
const quantityLabel = (v:number) => v.toLocaleString('pt-BR',{maximumFractionDigits:3});
const numeric = (v:FormDataEntryValue|null) => {const s=String(v??'').trim();if(!/^-?\d+(,\d{1,3})?$/.test(s))throw new Error('Informe a quantidade com até três casas decimais, usando vírgula.');return Number(s.replace(',','.'));};
const signedMoney = (v:string) => v.trim().startsWith('-') ? -parseMoney(v.trim().slice(1)) : parseMoney(v);
const string = (fd:FormData,name:string) => String(fd.get(name)??'');
const match = (search:string,...values:(string|undefined)[]) => !search || values.some(v=>v?.toLocaleLowerCase().includes(search.toLocaleLowerCase()));
const isViewer = (modal:Modal):modal is Exclude<Modal,FormModal|PurchaseModal> => ['purchase-detail','contact-history','sale-detail','bird-sales','bills','bill-detail','closing-detail','receipts','operations'].includes(modal.type);
function Field({label,children}:{label:string;children:ReactNode}) {return <label className="field"><span>{label}</span>{children}</label>;}
function Dialog({title,close,children}:{title:string;close:()=>void;children:ReactNode}) {
 const panel=useRef<HTMLElement>(null),closeRef=useRef(close);closeRef.current=close;
 useEffect(()=>{const previous=document.activeElement as HTMLElement|null;const container=panel.current;container?.querySelector<HTMLElement>('input,select,textarea,button')?.focus();const keyboard=(event:KeyboardEvent)=>{if(!container?.getClientRects().length)return;if(event.key==='Escape'){event.preventDefault();closeRef.current();}if(event.key==='Tab'){const controls=Array.from(container?.querySelectorAll<HTMLElement>('input:not([disabled]),select:not([disabled]),textarea:not([disabled]),button:not([disabled]),[tabindex="0"]')??[]);if(!controls.length)return;const first=controls[0],last=controls.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}}};document.addEventListener('keydown',keyboard);return()=>{document.removeEventListener('keydown',keyboard);previous?.focus();};},[]);
 // Rendered on <body>: the animated page wrapper would otherwise trap a fixed window inside the content column.
 return createPortal(<div className="legacy commercial-portal"><div className="modal" role="presentation" onMouseDown={event=>{if(event.target===event.currentTarget)closeRef.current();}}><section ref={panel} className="card commercial-dialog" role="dialog" aria-modal="true" aria-labelledby="commercial-dialog-title"><div className="row modal-heading"><h2 id="commercial-dialog-title">{title}</h2><button type="button" className="button secondary" onClick={close} aria-label="Fechar janela">Fechar</button></div>{children}</section></div></div>,document.body);
}
function Empty({children}:{children:ReactNode}) {return <p className="muted empty-state">{children}</p>;}
function BillStatus({state,scope,bill}:{state:State;scope:Props['scope'];bill:Bill}) {const remaining=billOutstanding(state,scope,bill);return <span className="status-badge">{bill.cancelled?'Cancelada':remaining===0?'Quitada':bill.dueDate<today()?'Atrasada':billPaid(state,scope,bill.id)>0?'Parcialmente paga':'Em aberto'}</span>;}

export default function Commercial(props:Props) {
 const {state,scope,search,command,notify,view='sales',target,navigate,uiContext}=props;const fixedKind=props.contactKind;
 const modulePanel=useRef<HTMLElement>(null),modalTrail=useRef<Modal[]>([]);
 const [modal,setModal]=useState<Modal|null>(()=>{const route=recallUiRoute<CommercialRoute>(uiContext,'commercial',target?.request);return restoreModal(route&&typeof route.from==='string'?route.modal:readUiContext<CommercialContext>(uiContext,'commercial:return',null),state,scope);});
 const [from,setFrom]=useUiState(uiContext,'commercial:from',''),[to,setTo]=useUiState(uiContext,'commercial:to',''),[saleFilter,setSaleFilter]=useUiState(uiContext,'commercial:sale-filter','todas'),[contactKind,setContactKind]=useUiState(uiContext,'commercial:contact-kind','todas'),[stockFilter,setStockFilter]=useUiState(uiContext,'commercial:stock-filter','todas');
 const [stockDisplay,setStockDisplay]=useUiState<'materials'|'purchases'>(uiContext,'commercial:stock-display','materials'),[purchaseStatus,setPurchaseStatus]=useUiState(uiContext,'commercial:purchase-status','todas');
 const mountedContext=useRef(`${scope}:${view}`);
 useEffect(()=>{if(mountedContext.current!==`${scope}:${view}`){setModal(null);modalTrail.current=[];mountedContext.current=`${scope}:${view}`;}},[scope,view]);
 useEffect(()=>{if(!modal)return;const back=(event:Event)=>{if(!modulePanel.current?.getClientRects().length)return;event.preventDefault();setModal(modalTrail.current.pop()??null);};window.addEventListener('recanto:back',back);return()=>window.removeEventListener('recanto:back',back);},[modal]);
 const contacts=state.contacts.filter(c=>c.scope===scope),sales=state.sales.filter(s=>s.scope===scope),accounts=state.accounts.filter(a=>a.scope===scope),bills=state.bills.filter(b=>b.scope===scope),payments=state.payments.filter(p=>p.scope===scope),products=state.products.filter(p=>p.scope===scope),purchases=state.purchases.filter(p=>p.scope===scope);
 useEffect(()=>{
  if(!target||target.view!==view)return;
  const route=recallUiRoute<CommercialRoute>(uiContext,'commercial',target.request);
  if(route&&typeof route.from==='string'){setModal(restoreModal(route.modal,state,scope));setFrom(route.from);setTo(route.to);setSaleFilter(route.saleFilter);setContactKind(route.contactKind);setStockFilter(route.stockFilter);setStockDisplay(route.stockDisplay);setPurchaseStatus(route.purchaseStatus);return;}
  if(target.filter)setModal(null);
  if(target.saleId){if(state.sales.some(s=>s.scope===scope&&s.id===target.saleId))setModal({type:'sale-detail',saleId:target.saleId});return;}
  if(target.contactId){const contact=state.contacts.find(c=>c.scope===scope&&c.id===target.contactId);if(contact)setModal({type:'contact-history',contact});return;}
  if(target.billId){if(state.bills.some(b=>b.scope===scope&&b.id===target.billId))setModal({type:'bill-detail',billId:target.billId});return;}
  if(target.birdId&&view==='sales'){setModal({type:'bird-sales',birdId:target.birdId});return;}
  if(target.createAction==='contact'){setModal({type:'contact'});return;}
  if(['sale','reservation','quote'].includes(target.createAction??'')){setModal({type:'sale',initialStatus:target.createAction==='quote'?'orçamento':target.createAction==='reservation'?'reservada':'vendida'});return;}
  if(target.createAction==='bill'){setModal({type:'bill'});return;}
  if(target.createAction==='product'){setStockDisplay('materials');setModal({type:'product'});return;}
  if(target.createAction==='purchase'){setStockDisplay('purchases');setModal({type:'purchase'});return;}
  if(view==='stock'&&target.filter){if(target.filter==='purchases')setStockDisplay('purchases');else{setStockDisplay('materials');setStockFilter(target.filter);}}
  if(view==='sales'&&target.filter){setFrom('');setTo('');setSaleFilter(({sales:'realizadas',reservations:'reservada',deliveries:'vendida',quotes:'orçamento'} as Record<string,string>)[target.filter]??target.filter);}
  if(view==='finance'&&['overdue','receivable','payable','sale-receivables','receipts','sale-receipts'].includes(target.filter??''))setModal(target.filter==='receipts'||target.filter==='sale-receipts'?{type:'receipts',allDates:true}:{type:'bills',direction:target.filter==='receivable'||target.filter==='sale-receivables'?'receber':target.filter==='payable'?'pagar':'ambas',initialStatus:target.filter==='overdue'?'atrasadas':'abertas',allDates:true,clearSearch:true,saleOnly:target.filter==='sale-receivables'});
 },[scope,view,target?.request,target?.view,target?.saleId,target?.contactId,target?.billId,target?.birdId,target?.filter,target?.createAction]);
 useEffect(()=>{const context=modalContext(modal);writeUiContext(uiContext,'commercial:return',context);rememberUiRoute<CommercialRoute>(uiContext,'commercial',target?.request,{modal:context,from,to,saleFilter,contactKind,stockFilter,stockDisplay,purchaseStatus});},[modal,uiContext,target?.request,from,to,saleFilter,contactKind,stockFilter,stockDisplay,purchaseStatus]);
 const contactName=(contactId:string|null)=>contacts.find(c=>c.id===contactId)?.name??'Sem contato';
 const inPeriod=(d:string)=>(!from||d>=from)&&(!to||d<=to);
 const transact=async(action:string,data:unknown)=>{try{await command(action,data);notify('Registro salvo.');}catch(error){notify(error instanceof Error?error.message:'Não foi possível salvar.');}};
 const saleItems=(sale:Sale)=>sale.items.map(item=>item.kind==='ave'?birdLabel(state.birds.find(b=>b.scope===scope&&b.id===item.refId)):item.description);
 const outstanding=(sale:Sale)=>bills.filter(b=>b.saleId===sale.id&&b.direction==='receber').reduce((n,b)=>n+billOutstanding(state,scope,b),0);
 const filteredSales=sales.filter(s=>inPeriod(s.date)&&match(search,s.number,contactName(s.contactId),s.notes,...s.items.map(i=>i.description),...saleItems(s))&&(saleFilter==='todas'||saleFilter==='realizadas'&&['vendida','entregue'].includes(s.status)||s.status===saleFilter)).slice().sort((a,b)=>b.date.localeCompare(a.date)||b.number.localeCompare(a.number));
 const periodPayments=payments.filter(p=>inPeriod(p.date));
 const filteredProducts=products.filter(p=>match(search,p.name,p.lot,p.unit)&&(stockFilter==='todas'||stockFilter==='low-stock'&&stockBalance(state,scope,p.id)<=p.minimum||stockFilter==='expired'&&!!p.expiryDate&&p.expiryDate<today()));
 const filteredPurchases=purchases.filter(p=>inPeriod(p.date)&&(purchaseStatus==='todas'||p.status===purchaseStatus)&&match(search,products.find(product=>product.id===p.productId)?.name,products.find(product=>product.id===p.productId)?.lot,contactName(p.supplierId),p.notes,p.id)).slice().sort((a,b)=>b.date.localeCompare(a.date)||b.createdAt.localeCompare(a.createdAt));

 const paymentCard=(p:State['payments'][number])=>{const bill=bills.find(b=>b.id===p.billId),sale=sales.find(s=>s.id===bill?.saleId);return <article className="card transaction-card commercial-payment-row" data-payment-id={p.id} key={p.id}><div><strong>{bill?.description}</strong><p>{dateLabel(p.date)} · {bill?.direction==='receber'?'Recebimento':'Pagamento'} · {contactName(bill?.contactId??null)}</p>{sale&&<p className="muted">Itens: {saleItems(sale).join(' · ')}</p>}</div><div><strong className="commercial-money">{money(p.amountCents)}</strong><p>{accounts.find(a=>a.id===p.accountId)?.name} · {p.method}</p><p>{p.reversed?`Estornado em ${dateLabel(p.reversalDate)}: ${p.reversalReason}`:p.reconciledAt?`Conferido em ${dateLabel(p.reconciledAt)}`:'Não conferido com extrato'}</p></div><div className="row action-row"><button className="button" onClick={()=>setModal({type:'bill-detail',billId:p.billId})}>Ver conta e pagamentos</button>{!p.reversed&&<><button className="button" onClick={()=>transact('payment.reconcile',{id:p.id,date:today()})}>Marcar conferido</button>{!bill?.cancelled&&bill?.category!=='Reembolso'&&<button className="button" onClick={()=>setModal({type:'reverse',paymentId:p.id})}>Estornar registro</button>}</>}</div></article>;};
 const saleSummary=(sale:Sale)=><article className="card transaction-card commercial-sale-row" data-sale-id={sale.id} key={sale.id}><div className="commercial-sale-identification"><h3>{sale.number}</h3><p>{contactName(sale.contactId)}</p><p className="muted">{dateLabel(sale.date)}</p><span className="status-badge">{sale.status}</span></div><div className="commercial-sale-items"><strong>Itens da operação</strong>{sale.items.map(item=><div key={item.id}><span>{item.kind==='ave'?birdLabel(state.birds.find(b=>b.scope===scope&&b.id===item.refId)):item.description}</span>{item.kind==='ave'&&item.refId&&<button className="button compact" onClick={()=>setModal({type:'bird-sales',birdId:item.refId!})}>Ver histórico comercial</button>}</div>)}</div><div className="commercial-sale-values"><span>Total <strong className="commercial-money">{money(sale.totalCents)}</strong></span><span>Recebido líquido <strong className="commercial-money">{money(salePaid(state,scope,sale.id))}</strong></span><span>Em aberto <strong className="commercial-money">{money(outstanding(sale))}</strong></span><p className="muted">Entrega: {sale.deliveryDate?dateLabel(sale.deliveryDate):'Não realizada'}</p></div><div className="row action-row"><button className="button" onClick={()=>setModal({type:'sale-detail',saleId:sale.id})}>Ver operação e pagamentos</button></div></article>;
 const period=<div className="row filter-bar"><Field label="Período inicial"><input type="date" value={from} onChange={e=>setFrom(e.target.value)}/></Field><Field label="Período final"><input type="date" value={to} onChange={e=>setTo(e.target.value)}/></Field></div>;
 return <section ref={modulePanel} className="commercial-module">
 {view==='contacts'&&<div className="ui flex flex-col gap-4">
  <div className="grid grid-cols-[minmax(0,1fr)_auto] items-center gap-3"><p className="text-sm text-muted-foreground">{(n=>`${n} ${fixedKind==='fornecedor'?(n===1?'fornecedor':'fornecedores'):(n===1?'cliente':'clientes')}`)(contacts.filter(c=>fixedKind?c.kind===fixedKind:c.kind!=='interessado').length)}</p><Button variant="brand" size="sm" className="h-9" onClick={()=>setModal({type:'contact'})}><Plus/>{fixedKind==='fornecedor'?'Novo fornecedor':'Novo cliente'}</Button></div>
  <ContactCards state={state} scope={scope} kind={fixedKind==='fornecedor'?'fornecedor':'cliente'} contacts={contacts.filter(c=>(fixedKind?c.kind===fixedKind:c.kind!=='interessado')&&match(search,c.name,c.phone,c.email,c.interest,c.taxId)).slice().sort((a,b)=>a.name.localeCompare(b.name,'pt-BR'))} onOpen={c=>setModal({type:'contact-history',contact:c})} onEdit={c=>setModal({type:'contact',contact:c})} onCreate={()=>setModal({type:'contact'})}/>
 </div>}
 {view==='sales'&&<div className="ui flex flex-col gap-4">
  <div className="flex flex-wrap items-center gap-2">
   <Button variant="brand" size="sm" className="h-9" disabled={!contacts.length} onClick={()=>setModal({type:'sale',initialStatus:'vendida'})}><Plus/>Venda</Button>
   <Button variant="secondary" size="sm" className="h-9" disabled={!contacts.length} onClick={()=>setModal({type:'sale',initialStatus:'reservada'})}><Plus/>Reserva</Button>
   <Button variant="secondary" size="sm" className="h-9" disabled={!contacts.length} onClick={()=>setModal({type:'sale',initialStatus:'orçamento'})}><Plus/>Orçamento</Button>
   {!contacts.length&&<span className="text-xs text-muted-foreground">Cadastre um cliente para começar.</span>}
  </div>
  <PeriodBar from={from} to={to} onChange={(f,t2)=>{setFrom(f);setTo(t2);}}/>
  <div className="grid grid-cols-2 gap-2">
   <MiniStat label="Vendas realizadas" tone="teal" value={money(sales.filter(s=>['vendida','entregue'].includes(s.status)&&inPeriod(s.date)).reduce((n,s)=>n+s.totalCents,0))} hint="Ver vendas" onClick={()=>setModal({type:'operations',criterion:'realizadas'})}/>
   <MiniStat label="Recebido no período" tone="leaf" value={money(payments.filter(p=>!p.reversed&&inPeriod(p.date)&&bills.some(b=>b.id===p.billId&&b.direction==='receber'&&b.saleId)).reduce((n,p)=>n+p.amountCents,0))} hint="Ver recebimentos" onClick={()=>setModal({type:'receipts'})}/>
  </div>
  <div className="flex flex-col gap-3">
   <div className="flex flex-wrap items-center justify-between gap-2"><h2 className="font-sans text-base font-bold">Operações</h2><span className="text-xs text-muted-foreground">{filteredSales.length} {filteredSales.length===1?'operação':'operações'}</span></div>
   <SegmentedTabs size="sm" value={saleFilter} onChange={setSaleFilter} options={[['todas','Todas'],['orçamento','Orçamentos'],['reservada','Reservas'],['realizadas','Vendas'],['entregue','Entregues'],['cancelada','Canceladas'],['devolvida','Devolvidas']].map(([value,label])=>({value:value!,label:label!}))}/>
   <SaleRows state={state} scope={scope} sales={filteredSales} onOpen={s=>setModal({type:'sale-detail',saleId:s.id})}/>
  </div>
 </div>}
 {view==='finance'&&(()=>{const totals=openTotals(state,scope);const list=periodPayments.filter(p=>{const bill=bills.find(b=>b.id===p.billId);const sale=sales.find(s=>s.id===bill?.saleId);return match(search,bill?.description,contactName(bill?.contactId??null),p.method,accounts.find(a=>a.id===p.accountId)?.name,...(sale?saleItems(sale):[]));});return <div className="ui flex flex-col gap-4">
  <div className="grid grid-cols-2 gap-2 lg:grid-cols-[1fr_1fr_auto]">
   <MiniStat label="Contas a receber" tone="sky" value={money(totals.receive)} hint={`${totals.receiveCount} em aberto`} onClick={()=>setModal({type:'bills',direction:'receber'})}/>
   <MiniStat label="Contas a pagar" tone="coral" value={money(totals.pay)} hint={`${totals.payCount} em aberto`} onClick={()=>setModal({type:'bills',direction:'pagar'})}/>
   <Button variant="brand" size="sm" className="col-span-2 h-10 self-center lg:col-span-1" onClick={()=>setModal({type:'bill'})}><Plus/>Nova conta</Button>
  </div>
  <div className="flex flex-col gap-3">
   <div className="flex flex-wrap items-end justify-between gap-2"><div><h2 className="font-sans text-base font-bold">Extrato</h2><p className="text-xs text-muted-foreground">Entradas e saídas do caixa. Toque no ✓ quando bater com o banco.</p></div></div>
   <PeriodBar from={from} to={to} onChange={(f,t2)=>{setFrom(f);setTo(t2);}}/>
   <StatementList state={state} scope={scope} payments={list} onOpenBill={b=>setModal({type:'bill-detail',billId:b.id})} onReconcile={p=>transact('payment.reconcile',{id:p.id,date:today()})} onReverse={p=>setModal({type:'reverse',paymentId:p.id})}/>
  </div>
 </div>;})()}
 {view==='stock'&&<>
  <div className="ui mb-4 flex flex-col gap-3">
   <div className="grid grid-cols-[minmax(0,1fr)_auto] items-center gap-3"><SegmentedTabs size="sm" value={stockDisplay} onChange={setStockDisplay} options={[{value:'materials',label:'Materiais'},{value:'purchases',label:'Compras'}]}/><div className="flex gap-2"><Button variant="brand" size="sm" className="h-9" onClick={()=>setModal({type:'purchase'})}><Plus/>Compra</Button><Button variant="secondary" size="sm" className="h-9" onClick={()=>{setStockDisplay('materials');setModal({type:'product'});}}><Plus/><span className="hidden sm:inline">Produto</span></Button></div></div>
   {stockDisplay==='materials'?<SegmentedTabs size="sm" value={stockFilter} onChange={setStockFilter} options={[{value:'todas',label:'Todos'},{value:'low-stock',label:'Estoque baixo'},{value:'expired',label:'Vencidos'}]}/>:<div className="flex flex-col gap-2"><PeriodBar from={from} to={to} onChange={(f,t2)=>{setFrom(f);setTo(t2);}}/><SegmentedTabs size="sm" value={purchaseStatus} onChange={setPurchaseStatus} options={[{value:'todas',label:'Todas'},{value:'ativa',label:'Ativas'},{value:'cancelada',label:'Canceladas'}]}/></div>}
  </div>
  {stockDisplay==='materials'?<>
   <div className="grid">{filteredProducts.map(p=>{const balance=stockBalance(state,scope,p.id);return <article className="card stock-card" key={p.id}><h2>{p.name}</h2><p>Lote {p.lot||'Não informado'} · saldo {quantityLabel(balance)} {p.unit} · mínimo {quantityLabel(p.minimum)} {p.unit}</p><p>{p.expiryDate?`Validade: ${dateLabel(p.expiryDate)}${p.expiryDate<today()?' · VENCIDO':''}`:'Sem validade informada'} {balance<=p.minimum?'· ESTOQUE BAIXO':''}</p><div className="row action-row"><button className="button primary" onClick={()=>setModal({type:'purchase',productId:p.id})}>Comprar este material</button><button className="button" onClick={()=>setModal({type:'stock',product:p})}>Registrar movimentação</button><button className="button" onClick={()=>setModal({type:'product',product:p})}>Editar cadastro</button></div><details><summary>Histórico de entradas e saídas</summary>{state.stock.filter(m=>m.scope===scope&&m.productId===p.id).slice().reverse().map(m=><div className="ledger-entry" key={m.id}><p>{dateLabel(m.date)} · {m.kind} · {quantityLabel(m.quantity)} {p.unit} · custo unitário {money(m.unitCostCents)} · {m.reason}</p>{m.purchaseId&&<button className="button compact" onClick={()=>setModal({type:'purchase-detail',purchaseId:m.purchaseId!})}>Ver compra vinculada</button>}</div>)}</details></article>;})}</div>{!products.length&&<Empty>Cadastre um material nesta primeira compra ou use Novo produto / lote. O estoque de produtos é separado das aves individuais.</Empty>}{products.length>0&&!filteredProducts.length&&<Empty>Nenhum material corresponde a este filtro.</Empty>}
  </>:<>

   <div className="commercial-record-list">{filteredPurchases.map(p=>{const product=products.find(product=>product.id===p.productId),bill=bills.find(bill=>bill.id===p.billId),refund=bills.find(bill=>bill.id===p.refundBillId);return <article className="card commercial-purchase-row" data-purchase-id={p.id} key={p.id}><div><h3>{product?.name??'Material'}</h3><p>Lote {product?.lot||'não informado'} · {contactName(p.supplierId)}</p><span className="status-badge">{p.status==='ativa'?'Compra ativa':'Compra cancelada'}</span></div><div><p>{dateLabel(p.date)} · {quantityLabel(p.quantity)} {product?.unit}</p><p>Vencimento {dateLabel(p.dueDate)}</p></div><div className="commercial-sale-values"><span>Total <strong className="commercial-money">{money(p.totalCents)}</strong></span><span>Pago <strong className="commercial-money">{money(billPaid(state,scope,p.billId))}</strong></span><span>Em aberto <strong className="commercial-money">{money(bill?billOutstanding(state,scope,bill):0)}</strong></span>{refund&&<p>Restituição a receber {money(billOutstanding(state,scope,refund))}</p>}</div><button className="button" onClick={()=>setModal({type:'purchase-detail',purchaseId:p.id})}>Ver compra</button></article>;})}</div>{!purchases.length&&<Empty>Nenhuma compra integrada foi registrada. Movimentos anteriores permanecem no histórico de cada material, sem despesas retroativas.</Empty>}{purchases.length>0&&!filteredPurchases.length&&<Empty>Nenhuma compra corresponde a este filtro.</Empty>}
  </>}
 </>}

 {modal&&isViewer(modal)&&<CommercialViewer key={JSON.stringify(modal)} {...props} modal={modal} close={()=>{modalTrail.current=[];setModal(null);}} open={next=>{modalTrail.current.push(modal);setModal(next);}} initialFrom={from} initialTo={to}/>}
 {modal&&!isViewer(modal)&&(modal.type==='purchase'||modal.type==='purchase-cancel')&&<PurchaseDialog key={`${modal.type}-${modal.purchaseId??'new'}`} {...props} modal={modal} close={recordId=>{const purchaseId=recordId??modal.purchaseId;if(view==='stock')setStockDisplay('purchases');setModal(purchaseId?{type:'purchase-detail',purchaseId}:null);}}/>}
 {modal&&modal.type==='sale'&&<Dialog title={modal.sale?'Editar orçamento':modal.initialStatus==='reservada'?'Nova reserva':modal.initialStatus==='orçamento'?'Novo orçamento':'Nova venda'} close={()=>setModal(null)}><SaleForm state={state} scope={scope} command={command} notify={notify} status={modal.sale?'orçamento':modal.initialStatus??'vendida'} sale={modal.sale} close={()=>setModal(null)} navigate={navigate}/></Dialog>}
 {modal&&!isViewer(modal)&&modal.type!=='purchase'&&modal.type!=='purchase-cancel'&&modal.type!=='sale'&&<CommercialForm key={modal.type==='payment'?modal.bill.id:modal.type==='closing'?`${modal.type}-${modal.accountId??''}`:modal.type} {...props} modal={modal} close={()=>setModal(modal.type==='payment'&&modal.returnDirection?{type:'bills',direction:modal.returnDirection}:null)}/>}
 </section>;
}

function CommercialViewer({state,scope,search,modal,close,open,initialFrom,initialTo,navigate}:Props&{modal:Exclude<Modal,FormModal|PurchaseModal>;close:()=>void;open:(modal:Modal)=>void;initialFrom:string;initialTo:string}) {
 const [query,setQuery]=useState(modal.type==='bills'&&modal.clearSearch?'':search),[status,setStatus]=useState(modal.type==='bills'?modal.initialStatus??'abertas':'abertas'),[from,setFrom]=useState(modal.type==='bills'&&modal.allDates?'':initialFrom),[to,setTo]=useState(modal.type==='bills'&&modal.allDates?'':initialTo);
 const contacts=state.contacts.filter(c=>c.scope===scope),sales=state.sales.filter(s=>s.scope===scope),bills=state.bills.filter(b=>b.scope===scope),birds=state.birds.filter(b=>b.scope===scope);
 const contactName=(contactId:string|null)=>contacts.find(c=>c.id===contactId)?.name??'Sem contato';
 const sale=modal.type==='sale-detail'?sales.find(s=>s.id===modal.saleId):undefined;
 const bill=modal.type==='bill-detail'?bills.find(b=>b.id===modal.billId):undefined;
 const closing=modal.type==='closing-detail'?state.closings.find(c=>c.scope===scope&&c.id===modal.closingId):undefined;
 const purchase=modal.type==='purchase-detail'?state.purchases.find(p=>p.scope===scope&&p.id===modal.purchaseId):undefined;
 const bird=modal.type==='bird-sales'?birds.find(b=>b.id===modal.birdId):undefined;
 const title=modal.type==='purchase-detail'?'Detalhes da compra':modal.type==='contact-history'?`Histórico de ${modal.contact.name}`:modal.type==='bills'?modal.direction==='ambas'?'Contas a pagar e receber':modal.direction==='receber'?'Contas a receber':'Contas a pagar':modal.type==='receipts'?modal.allDates?'Recebimentos de vendas':'Recebimentos de vendas no período':modal.type==='operations'?modal.criterion==='realizadas'?'Vendas realizadas no período':'Reservas ativas no período':modal.type==='sale-detail'?`Operação ${sale?.number??''}`:modal.type==='bill-detail'?bill?.description??'Detalhes da conta':modal.type==='closing-detail'?'Detalhes da conferência de caixa':`Histórico comercial · ${birdLabel(bird)}`;
 const summary=(s:Sale)=><article className="card transaction-card" key={s.id}><div className="row card-header"><h3>{s.number} · {contactName(s.contactId)}</h3><span className="status-badge">{s.status}</span></div><p>{dateLabel(s.date)} · total {money(s.totalCents)} · recebido líquido {money(salePaid(state,scope,s.id))} · saldo {money(bills.filter(b=>b.saleId===s.id&&b.direction==='receber').reduce((n,b)=>n+billOutstanding(state,scope,b),0))}</p><p>Itens: {s.items.map(i=>i.kind==='ave'?birdLabel(birds.find(b=>b.id===i.refId)):i.description).join(' · ')}</p><p>Entrega: {s.deliveryDate?dateLabel(s.deliveryDate):'Não realizada'}</p><button className="button" onClick={()=>open({type:'sale-detail',saleId:s.id})}>Ver operação e pagamentos</button></article>;
 const billRow=(b:Bill)=><article className="card transaction-card" data-bill-id={b.id} key={b.id}><div className="row card-header"><h3>{b.description}</h3><BillStatus state={state} scope={scope} bill={b}/></div><p>{b.direction==='receber'?'A receber':'A pagar'} · {contactName(b.contactId)} · {b.category} · vencimento {dateLabel(b.dueDate)}</p>{b.saleId&&<p className="muted">Itens: {sales.find(s=>s.id===b.saleId)?.items.map(i=>i.kind==='ave'?birdLabel(birds.find(bird=>bird.id===i.refId)):i.description).join(' · ')}</p>}<p>Total {money(b.amountCents)} · confirmado {money(billPaid(state,scope,b.id))} · saldo {money(billOutstanding(state,scope,b))}</p><div className="row action-row"><button className="button" onClick={()=>open({type:'bill-detail',billId:b.id})}>Ver detalhes</button>{billOutstanding(state,scope,b)>0&&<button className="button primary" disabled={!state.accounts.some(a=>a.scope===scope)} onClick={()=>open({type:'payment',bill:b,returnDirection:b.direction})}>{b.direction==='receber'?'Registrar recebimento':'Registrar pagamento'}</button>}</div></article>;
 const visibleBills=modal.type==='bills'?bills.filter(b=>(!modal.saleOnly||!!b.saleId)&&(modal.direction==='ambas'||b.direction===modal.direction)&&(!from||b.dueDate>=from)&&(!to||b.dueDate<=to)&&match(query,b.description,b.category,b.costCenter,contactName(b.contactId))&&(status==='todas'||status==='canceladas'&&b.cancelled||status==='quitadas'&&!b.cancelled&&billOutstanding(state,scope,b)===0||status==='abertas'&&billOutstanding(state,scope,b)>0||status==='atrasadas'&&b.dueDate<today()&&billOutstanding(state,scope,b)>0)).slice().sort((a,b)=>a.dueDate.localeCompare(b.dueDate)):[];
 const receiptPayments=state.payments.filter(p=>p.scope===scope&&!p.reversed&&(modal.type==='receipts'&&modal.allDates||!initialFrom||p.date>=initialFrom)&&(modal.type==='receipts'&&modal.allDates||!initialTo||p.date<=initialTo)&&bills.some(b=>b.id===p.billId&&b.direction==='receber'&&b.saleId));
 return <Dialog title={title} close={close}>
 {modal.type==='contact-history'&&<>
  <p>{modal.contact.kind} · {[modal.contact.phone,modal.contact.email].filter(Boolean).join(' · ')||'Contato não informado'}</p>
  <h3>Vendas, reservas e orçamentos</h3>{sales.filter(s=>s.contactId===modal.contact.id).slice().sort((a,b)=>b.date.localeCompare(a.date)).map(summary)}
  {!sales.some(s=>s.contactId===modal.contact.id)&&<Empty>Nenhuma venda, reserva ou orçamento registrado para este contato.</Empty>}
  {bills.some(b=>b.contactId===modal.contact.id&&!b.saleId)&&<><h3>Outras contas e movimentações</h3>{bills.filter(b=>b.contactId===modal.contact.id&&!b.saleId).slice().sort((a,b)=>b.dueDate.localeCompare(a.dueDate)).map(billRow)}</>}
  {birds.some(b=>b.supplierId===modal.contact.id)&&<><h3>Aves adquiridas deste fornecedor</h3>{birds.filter(b=>b.supplierId===modal.contact.id).map(b=><article className="card transaction-card" key={b.id}><BirdChip state={state} scope={scope} bird={b} size={40}/><p>{b.acquiredDate?dateLabel(b.acquiredDate):'Data não informada'} · aquisição {money(b.acquisitionCents)} · procedência: {b.origin}</p></article>)}</>}
  {state.purchases.some(p=>p.scope===scope&&p.supplierId===modal.contact.id)&&<><h3>Compras vinculadas ao fornecedor</h3>{state.purchases.filter(p=>p.scope===scope&&p.supplierId===modal.contact.id).slice().sort((a,b)=>b.date.localeCompare(a.date)).map(p=><article className="card transaction-card" key={p.id}><h4>{state.products.find(product=>product.id===p.productId&&product.scope===scope)?.name??'Material'}</h4><p>{dateLabel(p.date)} · total {money(p.totalCents)} · {p.status==='ativa'?'Compra ativa':'Compra cancelada'}</p><button className="button" onClick={()=>open({type:'purchase-detail',purchaseId:p.id})}>Ver compra e pagamentos</button></article>)}</>}
  {state.products.some(p=>p.scope===scope&&p.supplierId===modal.contact.id)&&<><h3>Compras de produtos / lotes atribuídos ao fornecedor</h3>{state.products.filter(p=>p.scope===scope&&p.supplierId===modal.contact.id&&state.stock.some(m=>m.scope===scope&&m.productId===p.id&&m.kind==='compra'&&!m.purchaseId)).map(p=><section className="record-group" key={p.id}><h4>{p.name} · lote {p.lot||'não informado'}</h4>{state.stock.filter(m=>m.scope===scope&&m.productId===p.id&&m.kind==='compra'&&!m.purchaseId).slice().reverse().map(m=><article className="card transaction-card" key={m.id}><p>{dateLabel(m.date)} · {quantityLabel(m.quantity)} {p.unit} · custo unitário {money(m.unitCostCents)} · total {money(itemTotal({quantity:m.quantity,unitCents:m.unitCostCents}))}</p><p>{m.reason}</p></article>)}</section>)}<p>A atribuição do fornecedor vem do cadastro atual do lote; os pagamentos das compras aparecem nas contas financeiras vinculadas ao contato.</p></>}
  {state.attachments.some(a=>a.scope===scope&&a.contactId===modal.contact.id)&&<><h3>Documentos do contato</h3>{state.attachments.filter(a=>a.scope===scope&&a.contactId===modal.contact.id).map(a=><AttachmentPreview key={a.id} attachment={a}/>)}</>}
 </>}
 {modal.type==='bird-sales'&&<>{sales.filter(s=>s.items.some(i=>i.kind==='ave'&&i.refId===modal.birdId)).slice().sort((a,b)=>b.date.localeCompare(a.date)).map(summary)}</>}
 {modal.type==='sale-detail'&&sale&&<SaleDetails state={state} scope={scope} sale={sale} open={open} navigate={navigate} close={close}/>}
 {modal.type==='bills'&&<>
  <div className="grid form-fields"><Field label="Buscar contas"><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Descrição, contato, categoria"/></Field><Field label="Situação"><select value={status} onChange={e=>setStatus(e.target.value)}><option value="abertas">Em aberto e parciais</option><option value="atrasadas">Atrasadas</option><option value="quitadas">Quitadas</option><option value="canceladas">Canceladas</option><option value="todas">Todas</option></select></Field><Field label="Vencimento inicial"><input type="date" value={from} onChange={e=>setFrom(e.target.value)}/></Field><Field label="Vencimento final"><input type="date" value={to} onChange={e=>setTo(e.target.value)}/></Field></div>
  <p>{visibleBills.length} contas · saldo no filtro {money(visibleBills.reduce((n,b)=>n+billOutstanding(state,scope,b),0))}</p><button className="button" onClick={()=>open({type:'bill',direction:modal.direction==='ambas'?undefined:modal.direction})}>Nova conta {modal.direction==='ambas'?'a pagar/receber':modal.direction==='receber'?'a receber':'a pagar'}</button>
  {!state.accounts.some(a=>a.scope===scope)&&<Empty>Cadastre uma conta financeira no painel para registrar recebimentos ou pagamentos.</Empty>}
  {visibleBills.map(billRow)}
  {!visibleBills.length&&<Empty>Nenhuma conta corresponde a este filtro.</Empty>}
 </>}
 {modal.type==='operations'&&<>{sales.filter(s=>(!initialFrom||s.date>=initialFrom)&&(!initialTo||s.date<=initialTo)&&(modal.criterion==='realizadas'?['vendida','entregue'].includes(s.status):s.status==='reservada')).slice().sort((a,b)=>b.date.localeCompare(a.date)).map(summary)}</>}
 {modal.type==='receipts'&&<><p>{receiptPayments.length} recebimentos · total {money(receiptPayments.reduce((n,p)=>n+p.amountCents,0))}</p>{receiptPayments.slice().sort((a,b)=>b.date.localeCompare(a.date)).map(p=>{const relatedBill=bills.find(b=>b.id===p.billId);return <article className="card transaction-card" data-payment-id={p.id} key={p.id}><strong>{relatedBill?.description}</strong><p>{dateLabel(p.date)} · {money(p.amountCents)} · {p.method}</p><button className="button" onClick={()=>open({type:'bill-detail',billId:p.billId})}>Ver conta e pagamentos</button></article>;})}{!receiptPayments.length&&<Empty>Nenhum recebimento de venda neste período.</Empty>}</>}
 {modal.type==='bill-detail'&&bill&&<BillDetails state={state} scope={scope} bill={bill} open={open}/>}
 {modal.type==='purchase-detail'&&purchase&&<PurchaseDetails state={state} scope={scope} purchase={purchase} onEdit={()=>open({type:'purchase',purchaseId:purchase.id})} onCancel={()=>open({type:'purchase-cancel',purchaseId:purchase.id})} onBill={bill=>open({type:'bill-detail',billId:bill.id})}/>}
 {modal.type==='closing-detail'&&closing&&<ClosingDetails state={state} scope={scope} closing={closing}/>}
 </Dialog>;
}

function PurchaseDialog({modal,close,...props}:Props&{modal:PurchaseModal;close:(recordId?:string)=>void}) {
 const [busy,setBusy]=useState(false);
 const purchase=props.state.purchases.find(p=>p.scope===props.scope&&p.id===modal.purchaseId);
 return <Dialog title={modal.type==='purchase-cancel'?'Cancelar compra':purchase?'Corrigir compra':'Registrar compra'} close={()=>{if(!busy)close();}}>{modal.type==='purchase-cancel'?(purchase?<CancelPurchaseForm {...props} purchase={purchase} close={close} onBusyChange={setBusy}/>:<Empty>Compra não encontrada nesta base.</Empty>):<PurchaseForm {...props} purchase={purchase} productId={modal.productId} close={close} onBusyChange={setBusy}/>}</Dialog>;
}

function SaleDetails({state,scope,sale,open,navigate,close}:{state:State;scope:Props['scope'];sale:Sale;open:(modal:Modal)=>void;navigate?:Props['navigate'];close:()=>void}) {
 const saleBills=state.bills.filter(b=>b.scope===scope&&b.saleId===sale.id),accounts=state.accounts.filter(a=>a.scope===scope);
 const openCents=saleBills.filter(b=>b.direction==='receber').reduce((n,b)=>n+billOutstanding(state,scope,b),0);
 return <>
  <p>{state.contacts.find(c=>c.scope===scope&&c.id===sale.contactId)?.name} · {dateLabel(sale.date)} · {sale.status}</p><p>Total {money(sale.totalCents)} · recebido líquido {money(salePaid(state,scope,sale.id))} · em aberto {money(openCents)}</p><p>Pagamento: {sale.status==='orçamento'?'Ainda sem cobrança':['cancelada','devolvida'].includes(sale.status)?'Encerrado com histórico preservado':openCents===0?'Quitado':'Parcial ou pendente'} · entrega: {sale.deliveryDate?dateLabel(sale.deliveryDate):'Não realizada'}</p>
  {sale.paymentPlan&&<p>Forma de pagamento: <strong>{sale.paymentPlan}</strong></p>}<h3>Itens da operação</h3>{sale.items.map(i=><article className="card transaction-card" key={i.id}>{i.kind==='ave'&&i.refId?<BirdChip state={state} scope={scope} birdId={i.refId} size={44}/>:<h4>{i.description}</h4>}<p>{i.description} · {quantityLabel(i.quantity)} × {money(i.unitCents)} = {money(itemTotal(i))}</p>{i.kind==='ave'&&i.refId&&navigate&&<button className="button" onClick={()=>{close();navigate({view:'birds',birdId:i.refId!});}}>Abrir ficha da ave</button>}</article>)}
  {(sale.discountCents>0||sale.feeCents>0)&&<p>Desconto {money(sale.discountCents)} · taxas {money(sale.feeCents)}</p>}{sale.notes&&<p>Observações internas: {sale.notes}</p>}
  <div className="row action-row">{sale.status==='orçamento'&&<><button className="button" onClick={()=>open({type:'sale',sale})}>Editar orçamento</button><button className="button" onClick={()=>open({type:'transition',sale,status:'reservada'})}>Reservar</button></>}{['orçamento','reservada'].includes(sale.status)&&<button className="button" onClick={()=>open({type:'transition',sale,status:'vendida'})}>Converter em venda</button>}{sale.status==='vendida'&&<button className="button" onClick={()=>open({type:'transition',sale,status:'entregue'})}>Registrar entrega</button>}{['orçamento','reservada','vendida'].includes(sale.status)&&<button className="button" onClick={()=>open({type:'transition',sale,status:'cancelada'})}>Cancelar com histórico</button>}{sale.status==='entregue'&&<button className="button" onClick={()=>open({type:'transition',sale,status:'devolvida'})}>Registrar devolução</button>}</div>
  <h3>Parcelas, sinais e pagamentos</h3>{!accounts.length&&saleBills.some(b=>billOutstanding(state,scope,b)>0)&&<Empty>Cadastre uma conta financeira para registrar o dinheiro recebido ou pago.</Empty>}
  {saleBills.map(b=><article className="card transaction-card" key={b.id}><h4>{b.description}</h4><p>Vencimento {dateLabel(b.dueDate)} · valor {money(b.amountCents)} · saldo {money(billOutstanding(state,scope,b))} · <BillStatus state={state} scope={scope} bill={b}/></p><div className="row action-row"><button className="button" onClick={()=>open({type:'bill-detail',billId:b.id})}>Ver detalhes da parcela</button>{billOutstanding(state,scope,b)>0&&<button className="button primary" disabled={!accounts.length} onClick={()=>open({type:'payment',bill:b})}>{sale.status==='reservada'?'Receber sinal/parcela':'Registrar pagamento parcial'}</button>}</div></article>)}
  {navigate&&<div className="row action-row"><button className="button" onClick={()=>{close();navigate({view:'documents',saleId:sale.id});}}>Documentos desta operação</button>{!sale.deliveryDate&&sale.items.filter(i=>i.kind==='ave'&&i.refId).map(i=><button key={i.id} className="button" onClick={()=>{close();navigate({view:'booklet',saleId:sale.id,birdId:i.refId!});}}>Caderneta · {birdLabel(state.birds.find(b=>b.scope===scope&&b.id===i.refId))}</button>)}</div>}
  {sale.deliveryDate&&<DeliveryReview state={state} scope={scope} sale={sale} navigate={navigate} selected={[]} onChange={()=>undefined} delivered/>}
  <h3>Histórico da operação</h3>{sale.statusHistory.map((h,i)=><p className="ledger-entry" key={i}>{dateLabel(h.date)} · {h.status} · {h.reason}</p>)}
  {state.attachments.some(a=>a.scope===scope&&a.saleId===sale.id)&&<><h3>Documentos da operação</h3>{state.attachments.filter(a=>a.scope===scope&&a.saleId===sale.id).map(a=><AttachmentPreview key={a.id} attachment={a}/>)}</>}
 </>;
}

function BillDetails({state,scope,bill,open}:{state:State;scope:Props['scope'];bill:Bill;open:(modal:Modal)=>void}) {
 const payments=state.payments.filter(p=>p.scope===scope&&p.billId===bill.id),sale=state.sales.find(s=>s.scope===scope&&s.id===bill.saleId),accounts=state.accounts.filter(a=>a.scope===scope);
 return <>
  <p>{bill.direction==='receber'?'A receber':'A pagar'} · <BillStatus state={state} scope={scope} bill={bill}/></p><p>Contato: {state.contacts.find(c=>c.scope===scope&&c.id===bill.contactId)?.name??'Sem contato'} · categoria {bill.category} · centro de custo {bill.costCenter||'não informado'}</p><p>Vencimento {dateLabel(bill.dueDate)} · total {money(bill.amountCents)} · confirmado {money(billPaid(state,scope,bill.id))} · saldo {money(billOutstanding(state,scope,bill))}</p>
  {bill.purchaseId&&state.purchases.some(p=>p.id===bill.purchaseId&&p.scope===scope)&&<button className="button" onClick={()=>open({type:'purchase-detail',purchaseId:bill.purchaseId!})}>Ver compra e estoque vinculados</button>}
  {sale&&<><h3>Operação e aves vinculadas</h3><p>{sale.number} · {sale.status}</p>{sale.items.filter(i=>i.kind==='ave').map(i=><p className="ledger-entry" key={i.id}><BirdChip state={state} scope={scope} birdId={i.refId} size={32}/></p>)}<button className="button" onClick={()=>open({type:'sale-detail',saleId:sale.id})}>Ver operação</button></>}
  {billOutstanding(state,scope,bill)>0&&<button className="button primary" disabled={!accounts.length} onClick={()=>open({type:'payment',bill,returnDirection:bill.direction})}>{bill.direction==='receber'?'Registrar recebimento':'Registrar pagamento'}</button>}
  {!accounts.length&&<Empty>Cadastre uma conta financeira para registrar a confirmação.</Empty>}
  <h3>Histórico de pagamentos</h3>{payments.slice().sort((a,b)=>b.date.localeCompare(a.date)).map(p=><article className="card transaction-card" key={p.id}><p>{dateLabel(p.date)} · {money(p.amountCents)} · {accounts.find(a=>a.id===p.accountId)?.name} · {p.method}</p><p>{p.reversed?`Estornado em ${dateLabel(p.reversalDate)}: ${p.reversalReason}`:p.reconciledAt?`Conferido em ${dateLabel(p.reconciledAt)}`:'Confirmado manualmente'}</p>{!p.reversed&&!bill.cancelled&&bill.category!=='Reembolso'&&<button className="button" onClick={()=>open({type:'reverse',paymentId:p.id})}>Estornar registro</button>}{state.attachments.filter(a=>a.scope===scope&&a.sourceType==='payment'&&a.sourceId===p.id).map(a=><AttachmentPreview key={a.id} attachment={a}/>)}</article>)}
  {!payments.length&&<Empty>Nenhum pagamento confirmado. O saldo será quitado pela soma dos lançamentos.</Empty>}
  {state.attachments.filter(a=>a.scope===scope&&(a.sourceType==='bill'&&a.sourceId===bill.id)).map(a=><AttachmentPreview key={a.id} attachment={a}/>)}
  <button className="button" onClick={()=>open({type:'bills',direction:bill.direction})}>Voltar para contas {bill.direction==='receber'?'a receber':'a pagar'}</button>
 </>;
}

function ClosingDetails({state,scope,closing}:{state:State;scope:Props['scope'];closing:CashClosing}) {
 const current=cashClosingSummary(state,scope,closing.accountId,closing.date);
 const changed=current.expectedCents!==closing.expectedCents||!!closing.snapshot&&(current.incomeCents!==closing.snapshot.incomeCents||current.expenseCents!==closing.snapshot.expenseCents||current.reversalCents!==closing.snapshot.reversalCents||current.transferInCents!==closing.snapshot.transferInCents||current.transferOutCents!==closing.snapshot.transferOutCents||current.paymentIds.slice().sort().join(',')!==closing.snapshot.paymentIds.slice().sort().join(',')||current.transferIds.slice().sort().join(',')!==closing.snapshot.transferIds.slice().sort().join(','));
 return <>
  <h3>{state.accounts.find(a=>a.scope===scope&&a.id===closing.accountId)?.name} · {dateLabel(closing.date)}</h3><p>Previsto no fechamento {money(closing.expectedCents)} · contado {money(closing.countedCents)} · diferença {money(closing.countedCents-closing.expectedCents)}</p>{closing.recordedAt&&<p>Registrado em {new Date(closing.recordedAt).toLocaleString('pt-BR')}</p>}
  {closing.snapshot&&<ClosingBreakdown summary={closing.snapshot}/>}
  {closing.notes&&<p>Observações: {closing.notes}</p>}
  {changed&&<p className="notice" role="status">Os movimentos considerados hoje diferem dos registrados no fechamento. O saldo recalculado para a data é {money(current.expectedCents)}. O saldo previsto originalmente ({money(closing.expectedCents)}) e o resumo do fechamento foram preservados.</p>}
  <p>Esta conferência preserva o saldo informado e os movimentos considerados. Ela não ajusta o saldo das contas automaticamente.</p>
 </>;
}
function ClosingBreakdown({summary}:{summary:Omit<ReturnType<typeof cashClosingSummary>,'expectedCents'>}) {
 return <div className="grid metrics-grid closing-breakdown"><article className="card metric-card"><strong>Saldo inicial da conta</strong><p className="metric-value">{money(summary.openingCents)}</p></article><article className="card metric-card"><strong>Recebimentos até a data</strong><p className="metric-value">{money(summary.incomeCents)}</p></article><article className="card metric-card"><strong>Pagamentos até a data</strong><p className="metric-value">{money(summary.expenseCents)}</p></article><article className="card metric-card"><strong>Transferências e estornos</strong><p>Entradas {money(summary.transferInCents)} · saídas {money(summary.transferOutCents)} · estornos líquidos {money(summary.reversalCents)}</p></article></div>;
}
function CommercialForm({state,scope,command,notify,modal,close,navigate,uiContext,contactKind}:Props&{modal:FormModal;close:()=>void}){
 const [error,setError]=useState('');const [busy,setBusy]=useState(false);const receiptKey=useRef(id());
 const [attachments,setAttachments]=useState<PendingAttachment[]>([]),[fileBusy,setFileBusy]=useState(false);
 const deliverySaleId=modal.type==='transition'&&modal.status==='entregue'?modal.sale.id:'';
 const deliveryContext=deliverySaleId?uiContext:undefined;
 const [deliverySelection,setDeliverySelection]=useUiState<DeliverySelection[]>(deliveryContext,`delivery:files:${deliverySaleId}`,[]);
 const [deliveryDate,setDeliveryDate]=useUiState(deliveryContext,`delivery:date:${deliverySaleId}`,today());
 const [deliveryReason,setDeliveryReason]=useUiState(deliveryContext,`delivery:reason:${deliverySaleId}`,'');
 const [closingAccount,setClosingAccount]=useState(modal.type==='closing'?modal.accountId??state.accounts.find(a=>a.scope===scope)?.id??'':'');
 const [closingDate,setClosingDate]=useState(today()),[counted,setCounted]=useState('');
 const [paymentAmount,setPaymentAmount]=useState(modal.type==='payment'?moneyInput(billOutstanding(state,scope,modal.bill)):'');
 const contacts=state.contacts.filter(c=>c.scope===scope),accounts=state.accounts.filter(a=>a.scope===scope),products=state.products.filter(p=>p.scope===scope);
 const initialSale=modal.type==='sale'?modal.sale:undefined;
 const saleStatus=modal.type==='sale'?(initialSale?.status==='orçamento'?'orçamento':modal.initialStatus??'vendida'):'vendida';
 const closingSummary=modal.type==='closing'&&closingAccount?cashClosingSummary(state,scope,closingAccount,closingDate):undefined;
 const existingClosing=modal.type==='closing'?state.closings.find(c=>c.scope===scope&&c.accountId===closingAccount&&c.date===closingDate):undefined;
 const previousClosing=modal.type==='closing'?state.closings.filter(c=>c.scope===scope&&c.accountId===closingAccount&&c.date<closingDate).slice().sort((a,b)=>b.date.localeCompare(a.date))[0]:undefined;
 const countedCents=(()=>{try{return counted?signedMoney(counted):null;}catch{return null;}})();
 const difference=closingSummary&&countedCents!==null?countedCents-closingSummary.expectedCents:null;
 const supportsAttachments=['contact','sale','bill','payment'].includes(modal.type);
 const [items,setItems]=useState<{kind:'ave'|'produto'|'serviço';refId:string;description:string;quantity:string;price:string}[]>(initialSale?.items.map(i=>({...i,refId:i.refId??'',quantity:quantityLabel(i.quantity).replaceAll('.',''),price:moneyInput(i.unitCents)}))??[{kind:'ave',refId:'',description:'',quantity:'1',price:'0,00'}]);
 const [discount,setDiscount]=useState(initialSale?moneyInput(initialSale.discountCents):'0,00');const [fee,setFee]=useState(initialSale?moneyInput(initialSale.feeCents):'0,00');
 const [partCount,setPartCount]=useState('1');const [payNow,setPayNow]=useState(false);
 const cashAccount=async()=>{const existing=state.accounts.find(a=>a.scope===scope);if(existing)return existing.id;const created=await command('account.save',{name:'Caixa',openingCents:0});if(!created)throw new Error('Não foi possível preparar o caixa.');return created;};
 const saleTotal=()=>items.reduce((sum,i)=>sum+itemTotal({quantity:numeric(i.quantity),unitCents:parseMoney(i.price)}),0)-parseMoney(discount)+parseMoney(fee);
 const plan=(count:number,start:string,total:number)=>{if(!Number.isInteger(count)||count<1||count>120)throw new Error('Use de 1 a 120 parcelas.');const base=new Date(start+'T12:00:00Z');if(Number.isNaN(base.valueOf()))throw new Error('Informe o primeiro vencimento.');const amounts=Array.from({length:count},(_,index)=>Math.floor(total/count)+(index<total%count?1:0));return amounts.map((amountCents,index)=>{const month=base.getUTCMonth()+index;const last=new Date(Date.UTC(base.getUTCFullYear(),month+1,0,12)).getUTCDate();const dueDate=new Date(Date.UTC(base.getUTCFullYear(),month,Math.min(base.getUTCDate(),last),12)).toISOString().slice(0,10);return {dueDate,amountCents};});};
 const contactOptions=<><option value="">Sem contato</option>{contacts.map(c=><option key={c.id} value={c.id}>{c.name} · {c.kind}</option>)}</>;
 const accountOptions=<>{accounts.map(a=><option key={a.id} value={a.id}>{a.name}</option>)}</>;
 const save=async(event:FormEvent<HTMLFormElement>)=>{
  event.preventDefault();if(busy||fileBusy)return;setError('');const fd=new FormData(event.currentTarget);setBusy(true);
  try{let action='',payload:unknown;
   if(modal.type==='contact'){action='contact.save';payload={id:modal.contact?.id,kind:string(fd,'kind'),name:string(fd,'name'),phone:string(fd,'phone'),email:string(fd,'email'),address:string(fd,'address'),taxId:string(fd,'taxId'),interest:string(fd,'interest'),notes:string(fd,'notes')};}
   else if(modal.type==='sale'){const total=saleTotal();action='sale.save';payload={id:initialSale?.id,contactId:string(fd,'contactId'),date:string(fd,'date'),status:string(fd,'status'),items:items.map(i=>({kind:i.kind,refId:i.refId||null,description:i.description,quantity:numeric(i.quantity),unitCents:parseMoney(i.price)})),discountCents:parseMoney(discount),feeCents:parseMoney(fee),notes:string(fd,'notes'),installments:string(fd,'status')==='orçamento'?[]:plan(Number(partCount),string(fd,'dueDate'),total),receipt:!initialSale&&fd.get('payNow')?{amountCents:parseMoney(string(fd,'payAmount')),method:string(fd,'payMethod')}:undefined};}
   else if(modal.type==='payment'){action='payment.record';payload={billId:modal.bill.id,accountId:string(fd,'accountId')||await cashAccount(),date:string(fd,'date'),amountCents:parseMoney(string(fd,'amount')),method:string(fd,'method'),idempotencyKey:receiptKey.current};}
   else if(modal.type==='transition'){action='sale.transition';payload={id:modal.sale.id,status:modal.status,date:string(fd,'date'),reason:string(fd,'reason'),deliveryFiles:modal.status==='entregue'?deliverySelection:undefined,refundAccountId:string(fd,'refundAccountId')||undefined,installments:modal.sale.status==='orçamento'&&['reservada','vendida'].includes(modal.status)?plan(Number(partCount),string(fd,'dueDate'),modal.sale.totalCents):[]};}
   else if(modal.type==='account'){action='account.save';payload={name:string(fd,'name'),openingCents:signedMoney(string(fd,'opening'))};}
   else if(modal.type==='bill'){action='bill.save';payload={direction:string(fd,'direction'),contactId:string(fd,'contactId')||null,description:string(fd,'description'),dueDate:string(fd,'dueDate'),amountCents:parseMoney(string(fd,'amount')),category:string(fd,'category'),costCenter:string(fd,'costCenter')};}
   else if(modal.type==='transfer'){action='transfer.create';payload={fromAccountId:string(fd,'from'),toAccountId:string(fd,'to'),date:string(fd,'date'),amountCents:parseMoney(string(fd,'amount')),reason:string(fd,'reason')};}
   else if(modal.type==='closing'){action='closing.create';payload={accountId:string(fd,'accountId'),date:string(fd,'date'),countedCents:signedMoney(string(fd,'counted')),notes:string(fd,'notes')};}
   else if(modal.type==='product'){action='product.save';payload={id:modal.product?.id,name:string(fd,'name'),unit:string(fd,'unit'),minimum:numeric(fd.get('minimum')),lot:string(fd,'lot'),expiryDate:string(fd,'expiryDate'),supplierId:string(fd,'supplierId')||null};}
   else if(modal.type==='stock'){const kind=string(fd,'kind');let amount=numeric(fd.get('quantity'));if(['consumo','perda'].includes(kind))amount=-Math.abs(amount);action='stock.create';payload={productId:modal.product.id,date:string(fd,'date'),kind,quantity:amount,unitCostCents:parseMoney(string(fd,'unitCost')),reason:string(fd,'reason'),allowNegative:fd.get('allowNegative')==='on'};}
   else if(modal.type==='reverse'){action='payment.reverse';payload={id:modal.paymentId,date:string(fd,'date'),reason:string(fd,'reason')};}
   await command(attachments.length?'save.withAttachments':action,attachments.length?{action,data:payload,attachments}:payload);notify('Registro salvo.');close();
  }catch(err){setError(err instanceof Error?err.message:'Não foi possível salvar.');}finally{setBusy(false);}
 };
 const commonDate=<Field label="Data">{deliverySaleId?<input name="date" type="date" value={deliveryDate} onChange={event=>setDeliveryDate(event.target.value)} required/>:<input name="date" type="date" defaultValue={today()} required/>}</Field>;
 const commonReason=<Field label="Motivo / justificativa">{deliverySaleId?<textarea name="reason" required maxLength={150} value={deliveryReason} onChange={event=>setDeliveryReason(event.target.value)}/>:<textarea name="reason" required maxLength={150}/>}</Field>;
 const installments=<div className="row form-row"><Field label="Número de parcelas"><input inputMode="numeric" type="number" min="1" max="120" value={partCount} onChange={e=>setPartCount(e.target.value)}/></Field><Field label="Primeiro vencimento"><input name="dueDate" type="date" defaultValue={today()} required/></Field></div>;
 const title=modal.type==='contact'?'Cadastro de contato':modal.type==='sale'?initialSale?'Editar orçamento':saleStatus==='reservada'?'Registrar reserva':saleStatus==='orçamento'?'Registrar orçamento':'Registrar venda':modal.type==='payment'?modal.bill.direction==='receber'?'Confirmar recebimento':'Confirmar pagamento':modal.type==='transition'?`Registrar ${modal.status}`:modal.type==='account'?'Conta financeira':modal.type==='bill'?'Conta a pagar/receber':modal.type==='transfer'?'Transferência entre contas':modal.type==='closing'?'Conferência / fechamento de caixa':modal.type==='product'?'Produto e lote':modal.type==='stock'?'Movimentação de estoque':'Estornar registro de pagamento';
 return <Dialog title={title} close={()=>{if(!busy&&!fileBusy)close();}}><form className="record-form" onSubmit={save}>
  {modal.type==='contact'&&<><div className="grid form-fields"><Field label="Nome"><input name="name" required maxLength={150} defaultValue={modal.contact?.name}/></Field><Field label="Tipo"><select name="kind" defaultValue={modal.contact?.kind??contactKind??'cliente'}><option value="cliente">Cliente</option><option value="fornecedor">Fornecedor</option>{modal.contact?.kind==='interessado'&&<option value="interessado">Interessado (antigo)</option>}</select></Field><Field label="Telefone"><input name="phone" type="tel" defaultValue={modal.contact?.phone}/></Field><Field label="E-mail"><input name="email" type="email" defaultValue={modal.contact?.email}/></Field><Field label="CPF/CNPJ (opcional)"><input name="taxId" defaultValue={modal.contact?.taxId} maxLength={30}/></Field><Field label={(modal.contact?.kind??contactKind)==='fornecedor'?'O que fornece (materiais, insumos, aves)':'Espécie / mutação de interesse'}><input name="interest" defaultValue={modal.contact?.interest}/></Field></div><Field label="Endereço (opcional)"><textarea name="address" defaultValue={modal.contact?.address}/></Field><Field label="Observações e acompanhamento interno"><textarea name="notes" defaultValue={modal.contact?.notes}/></Field></>}
  {modal.type==='sale'&&<><div className="grid form-fields"><Field label="Cliente"><select name="contactId" required defaultValue={initialSale?.contactId??''}><option value="">Selecione</option>{contacts.map(c=><option key={c.id} value={c.id}>{c.name}</option>)}</select></Field><Field label="Data da operação"><input name="date" type="date" required defaultValue={initialSale?.date??today()}/></Field><Field label="Situação comercial"><input type="hidden" name="status" value={saleStatus}/><input value={saleStatus==='vendida'?'Venda':saleStatus==='reservada'?'Reserva':'Orçamento'} readOnly/></Field></div><p>Reservas bloqueiam a ave. A venda baixa produtos e cria parcelas. O recebimento é registrado separadamente.</p>
   {items.map((item,index)=><fieldset className="card sale-item-form" key={index}><legend>Item {index+1}</legend><div className="grid form-fields"><Field label="Tipo do item"><select value={item.kind} onChange={e=>setItems(items.map((v,i)=>i===index?{...v,kind:e.target.value as typeof item.kind,refId:'',description:'',quantity:'1'}:v))}><option value="ave">Ave individual</option><option value="produto">Produto / lote</option><option value="serviço">Serviço</option></select></Field>{item.kind!=='serviço'&&<Field label={item.kind==='ave'?'Ave':'Produto / lote'}><select required value={item.refId} onChange={e=>{const selected=e.target.value;const description=item.kind==='ave'?birdLabel(state.birds.find(b=>b.id===selected&&b.scope===scope)):products.find(p=>p.id===selected)?.name??'';setItems(items.map((v,i)=>i===index?{...v,refId:selected,description}:v));}}><option value="">Selecione</option>{item.kind==='ave'?state.birds.filter(b=>b.scope===scope).map(b=><option key={b.id} value={b.id}>{birdLabel(b)} · {b.status}</option>):products.map(p=><option key={p.id} value={p.id}>{p.name} · lote {p.lot||'não informado'} · {quantityLabel(stockBalance(state,scope,p.id))} {p.unit}</option>)}</select></Field>}<Field label="Descrição"><input value={item.description} required maxLength={150} onChange={e=>setItems(items.map((v,i)=>i===index?{...v,description:e.target.value}:v))}/></Field><Field label="Quantidade"><input inputMode="decimal" value={item.quantity} readOnly={item.kind==='ave'} onChange={e=>setItems(items.map((v,i)=>i===index?{...v,quantity:e.target.value}:v))}/></Field><Field label="Valor unitário (R$)"><input inputMode="decimal" required value={item.price} onChange={e=>setItems(items.map((v,i)=>i===index?{...v,price:e.target.value}:v))}/></Field></div><button type="button" className="button" disabled={items.length===1} onClick={()=>setItems(items.filter((_,i)=>i!==index))}>Remover item {index+1}</button></fieldset>)}
   <button type="button" className="button" onClick={()=>setItems([...items,{kind:'serviço',refId:'',description:'',quantity:'1',price:'0,00'}])}>Adicionar item</button><div className="row form-row"><Field label="Desconto (R$)"><input inputMode="decimal" required value={discount} onChange={e=>setDiscount(e.target.value)}/></Field><Field label="Taxas (R$)"><input inputMode="decimal" required value={fee} onChange={e=>setFee(e.target.value)}/></Field></div><p className="sale-total">Total: {(()=>{try{return money(saleTotal());}catch{return 'Confira valores e quantidades';}})()}</p>{saleStatus!=='orçamento'&&installments}<p>As parcelas são mensais, distribuídas em centavos; diferenças de um centavo ficam nas primeiras parcelas. Orçamentos ainda não geram cobranças.</p>{saleStatus!=='orçamento'&&!initialSale&&<fieldset className="record-form-section"><legend>Pagamento</legend><label className="check"><input type="checkbox" name="payNow" checked={payNow} onChange={e=>setPayNow(e.target.checked)}/>{saleStatus==='reservada'?'O cliente já pagou um sinal':'Já recebi (total ou parte)'}</label>{payNow&&<div className="grid form-fields"><Field label="Valor recebido agora (R$)"><input name="payAmount" inputMode="decimal" required defaultValue={(()=>{try{return moneyInput(saleTotal());}catch{return '0,00';}})()}/></Field><Field label="Forma de pagamento"><select name="payMethod"><option>Pix</option><option>Dinheiro</option><option>Cartão de crédito</option><option>Cartão de débito</option><option>Transferência</option><option>Boleto</option><option>Outro</option></select></Field></div>}{!payNow&&<p className="muted">O valor fica como “a receber” até você registrar o pagamento.</p>}</fieldset>}<Field label="Observações internas"><textarea name="notes" defaultValue={initialSale?.notes}/></Field></>}
  {modal.type==='payment'&&<><p>{modal.bill.description} · em aberto {money(billOutstanding(state,scope,modal.bill))}</p>{accounts.length>1?<Field label="Onde o dinheiro entrou ou saiu"><select name="accountId" required defaultValue={accounts[0]?.id}>{accountOptions}</select></Field>:<input type="hidden" name="accountId" value={accounts[0]?.id??''}/>}{commonDate}<Field label="Valor confirmado (R$)"><input name="amount" inputMode="decimal" required value={paymentAmount} onChange={e=>setPaymentAmount(e.target.value)}/></Field><button type="button" className="button" onClick={()=>setPaymentAmount(moneyInput(billOutstanding(state,scope,modal.bill)))}>Usar saldo total</button><p>Para um pagamento parcial, informe somente o valor efetivamente recebido ou pago. A quitação ocorre quando os lançamentos completam o saldo.</p><Field label="Forma de pagamento"><select name="method"><option>Pix</option><option>Dinheiro</option><option>Cartão de crédito</option><option>Cartão de débito</option><option>Transferência</option><option>Boleto</option><option>Outro</option></select></Field><p>Confirme somente após verificar o dinheiro recebido ou pago. Nenhuma confirmação bancária automática é feita.</p></>}
  {modal.type==='transition'&&<><p>{modal.sale.number} · {money(modal.sale.totalCents)}</p>{modal.status==='entregue'&&<DeliveryReview state={state} scope={scope} sale={modal.sale} navigate={navigate} selected={deliverySelection} onChange={setDeliverySelection} onBusyChange={setFileBusy} disabled={busy}/>} {commonDate}{commonReason}{modal.sale.status==='orçamento'&&['reservada','vendida'].includes(modal.status)&&installments}{['cancelada','devolvida'].includes(modal.status)&&salePaid(state,scope,modal.sale.id)>0&&<><p>Reembolso integral manual: {money(salePaid(state,scope,modal.sale.id))}. Confirme após efetuar o reembolso. O recebimento original ficará no histórico.</p><Field label="Conta do reembolso"><select name="refundAccountId" required><option value="">Selecione</option>{accountOptions}</select></Field></>}{modal.status==='entregue'&&<p>A entrega vincula o cliente à ave e preserva a procedência. Caderneta e documentos devem ser revisados na área Documentos.</p>}</>}
  {modal.type==='account'&&<><Field label="Nome da conta"><input name="name" required maxLength={150}/></Field><Field label="Saldo inicial (R$)"><input name="opening" inputMode="decimal" defaultValue="0,00" required/></Field></>}
  {modal.type==='bill'&&<><div className="grid form-fields"><Field label="Tipo"><select name="direction" defaultValue={modal.direction??'pagar'}><option value="pagar">A pagar</option><option value="receber">A receber</option></select></Field><Field label="Descrição"><input name="description" required maxLength={150}/></Field><Field label="Cliente / fornecedor (opcional)"><select name="contactId">{contactOptions}</select></Field><Field label="Vencimento"><input name="dueDate" type="date" required defaultValue={today()}/></Field><Field label="Valor (R$)"><input name="amount" required inputMode="decimal"/></Field><Field label="Categoria"><input name="category" list="commercial-categories" required/><datalist id="commercial-categories">{state.settings.categories.map(c=><option key={c}>{c}</option>)}</datalist></Field><Field label="Centro de custo"><input name="costCenter"/></Field></div><p>Use categorias Aporte ou Retirada para movimentos do proprietário. A conta fica pendente até confirmação do pagamento.</p></>}
  {modal.type==='transfer'&&<><div className="grid form-fields"><Field label="Conta de origem"><select name="from" required>{accountOptions}</select></Field><Field label="Conta de destino"><select name="to" required defaultValue={accounts[1]?.id}>{accountOptions}</select></Field></div>{commonDate}<Field label="Valor (R$)"><input name="amount" required inputMode="decimal"/></Field>{commonReason}<p>A transferência altera apenas saldos entre suas contas.</p></>}
  {modal.type==='closing'&&<>
   <div className="grid form-fields"><Field label="Conta financeira"><select name="accountId" required value={closingAccount} onChange={e=>setClosingAccount(e.target.value)}>{accountOptions}</select></Field><Field label="Data do fechamento"><input name="date" type="date" required max={today()} value={closingDate} onChange={e=>setClosingDate(e.target.value)}/></Field></div>
   {previousClosing&&<p>Conferência anterior: {dateLabel(previousClosing.date)} · contado {money(previousClosing.countedCents)} · diferença {money(previousClosing.countedCents-previousClosing.expectedCents)}</p>}
   {closingSummary&&<><h3>Movimentos acumulados até {dateLabel(closingDate)}</h3><ClosingBreakdown summary={closingSummary}/><p>Saldo previsto para a data: <strong>{money(closingSummary.expectedCents)}</strong> · {closingSummary.paymentIds.length} registros de pagamento · {closingSummary.transferIds.length} transferências</p></>}
   <Field label="Saldo contado (R$)"><input name="counted" required inputMode="decimal" value={counted} onChange={e=>setCounted(e.target.value)}/></Field>
   {difference!==null&&<p className="notice" role="status">{difference===0?'Caixa confere com os lançamentos.':difference>0?`Valor contado acima do previsto: ${money(difference)}.`:`Valor contado abaixo do previsto: ${money(-difference)}.`}</p>}
   <Field label="Observações / diferença identificada"><textarea name="notes" required={difference!==null&&difference!==0} maxLength={2000} placeholder="Explique qualquer diferença e como foi conferida."/></Field>
   {existingClosing&&<p className="error" role="alert">Já existe uma conferência desta conta nesta data: previsto {money(existingClosing.expectedCents)} · contado {money(existingClosing.countedCents)}. Consulte o histórico antes de lançar outro fechamento.</p>}
   <p>A conferência salva os valores e movimentos considerados naquele momento. Ela não zera o caixa nem ajusta o saldo; diferenças exigem uma explicação.</p>
  </>}
  {modal.type==='product'&&<><div className="grid form-fields"><Field label="Produto / material"><input name="name" required maxLength={150} defaultValue={modal.product?.name}/></Field><Field label="Unidade (kg, g, un, L etc.)"><input name="unit" required maxLength={150} defaultValue={modal.product?.unit??'un'}/></Field><Field label="Estoque mínimo"><input name="minimum" inputMode="decimal" required defaultValue={String(modal.product?.minimum??0).replace('.',',')}/></Field><Field label="Lote"><input name="lot" maxLength={150} defaultValue={modal.product?.lot}/></Field><Field label="Validade (opcional)"><input name="expiryDate" type="date" defaultValue={modal.product?.expiryDate}/></Field><Field label="Fornecedor (opcional)"><select name="supplierId" defaultValue={modal.product?.supplierId??''}>{contactOptions}</select></Field></div></>}
  {modal.type==='stock'&&<><p>{modal.product.name} · saldo {quantityLabel(stockBalance(state,scope,modal.product.id))} {modal.product.unit}</p>{commonDate}<Field label="Movimentação"><select name="kind"><option value="compra">Compra / entrada avulsa (somente estoque)</option><option value="consumo">Consumo interno</option><option value="perda">Perda</option><option value="ajuste">Ajuste com quantidade assinada</option><option value="devolução">Devolução / entrada</option></select></Field><Field label={`Quantidade (${modal.product.unit})`}><input name="quantity" inputMode="decimal" required/></Field><Field label="Custo unitário registrado (R$)"><input name="unitCost" inputMode="decimal" required defaultValue="0,00"/></Field>{commonReason}<label className="field"><span><input name="allowNegative" type="checkbox"/> Autorizar saldo negativo excepcional, com a justificativa acima</span></label><p>Consumo e perda registram saída. Ajuste aceita valor negativo. A entrada avulsa registra apenas quantidade e custo. Para vincular uma compra ao Financeiro, use Registrar compra no painel de Materiais.</p></>}
  {modal.type==='reverse'&&<>{commonDate}{commonReason}<p>O estorno desfaz um registro financeiro incorreto, preservando o histórico e reabrindo o saldo da conta a pagar/receber. Para cancelar uma venda e reembolsar, use a ação na venda.</p></>}
  {supportsAttachments&&<AttachmentPicker value={attachments} onChange={setAttachments} category={modal.type==='contact'?'Contato':modal.type==='sale'?'Venda / reserva':modal.type==='payment'?'Comprovante de pagamento':'Conta financeira'} disabled={busy} onBusyChange={setFileBusy}/>}
  {error&&<p className="error" role="alert">{error}</p>}<div className="row modal-actions"><button type="submit" className="button primary" disabled={busy||fileBusy||!!existingClosing}>{busy?'Salvando…':'Confirmar e salvar'}</button><button type="button" className="button" disabled={busy||fileBusy} onClick={close}>Cancelar</button></div>
 </form></Dialog>;
}
